#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int N, K, U;
    if (!(cin >> N >> K >> U)) return 0;

    vector<vector<int>> num_to_cards(U + 1);
    for (int i = 1; i <= N; ++i) {
        for (int j = 0; j < K; ++j) {
            int num;
            cin >> num;
            num_to_cards[num].push_back(i);
        }
    }

    vector<int> remaining(N + 1, K);
    vector<int> winners;

    for (int i = 0; i < U; ++i) {
        int drawn;
        cin >> drawn;
        if (winners.empty()) {
            for (int card_id : num_to_cards[drawn]) {
                remaining[card_id]--;
                if (remaining[card_id] == 0) {
                    winners.push_back(card_id);
                }
            }
        }
    }

    sort(winners.begin(), winners.end());

    for (size_t i = 0; i < winners.size(); ++i) {
        if (i > 0) cout << " ";
        cout << winners[i];
    }
    cout << "\n";

    return 0;
}
